// Some portions generated by Claude
export type GraphNodeType = {
  id: string;
  label: string;
};

export type GraphNode = {
  id: string;
  label: string;
  kind: "iri" | "literal" | "blank";
  types?: GraphNodeType[];
  datatype?: string;
  language?: string;
  termValue?: string;
  pinned?: boolean;
  x?: number;
  y?: number;
};

export type GraphEdge = {
  id: string;
  source: string;
  predicate: string;
  label: string;
  target: string;
  batchId?: string;
};

/**
 * A statement whose object is an RDF 1.2 triple term: a reifier's `rdf:reifies <<( s p o )>>`, or any other
 * statement about a statement (`ex:doubts <<( s p o )>>`). The canvas draws it from its source node to the middle of
 * the edge of `s p o` when that edge is drawn.
 */
export type StatementLink = {
  id: string;
  /** The node that says something about the statement. */
  source: string;
  predicate: string;
  label: string;
  /** The statement the triple term names: its subject, predicate and object (node ids) and its edge's id. */
  subject: string;
  statementPredicate: string;
  object: string;
  statementEdgeId: string;
  batchId?: string;
};

export type Graph = {
  nodes: GraphNode[];
  edges: GraphEdge[];
  revision: number;
  statementLinks?: StatementLink[];
};

export type PointerPosition = {
  x: number;
  y: number;
};

export type GraphBox = PointerPosition & {
  width: number;
  height: number;
};

export type EdgeCurve = {
  path: string;
  start: PointerPosition;
  /** The quadratic's control point; for a stepped route, the route's middle. */
  control: PointerPosition;
  end: PointerPosition;
  /** A stepped route's corners from start to end (both included); absent for a quadratic curve. */
  points?: PointerPosition[];
};

/** A stepped route through the gaps between cards, valid while both cards keep the centres it was computed for. */
export type EdgeRoute = {
  source: PointerPosition;
  target: PointerPosition;
  /** From the source card's border to the target card's border, corners included. */
  points: PointerPosition[];
};

export type EdgeLabelPlacement = {
  point: PointerPosition;
  anchor: PointerPosition;
};

export type GraphTransform = {
  x: number;
  y: number;
  k: number;
};
